script:
(function () {
  'use strict';
  // Three-way comparison: fixed-rate mortgage vs fully amortizing ARM vs interest-only ARM.
  //   Amortizing payment M = B * i / (1 - (1 + i)^-n), i = rate / 12, n = months left (M = B / n at 0%).
  //   Interest-only payment = B * i. At the end of the interest-only period the unpaid balance is
  //   amortized over the months left on the term (the recast).
  //   ARM rates stay fixed for their fixed period, then change by the expected amount every 6 or 12
  //   months, limited by the first/later adjustment caps, the lifetime cap (start + cap) and the floor;
  //   the payment is re-figured over the months left at every rate change. Worst case = the rate rises
  //   by the full cap at every adjustment.
  //   Over the horizon: total paid = interest + principal repaid; balance left = loan - principal repaid.
  //   The loan with the least interest over the horizon is the cheapest to hold to a sale or refinance.
  // Verified in Node (scratchpad b6mtg/ai.test.js) against closed-form amortization: $400,000 over
  //   30 yrs, 7-year horizon, +0.25% a year after the fixed periods: fixed 6.5% = $2,528.27/mo, interest
  //   over 84 months $174,039.84 (= 84M - (L - B84)), balance $361,664.98; 5-year ARM at 5.875% =
  //   $2,366.15, then $2,422.94 at 6.125% and 6.375%: interest $159,275.03, balance $358,485.65;
  //   7-year interest-only ARM at 6.125% = $2,041.67, $171,500.00 interest, balance unchanged, recast at
  //   6.375% over 276 months = $2,765.80; every balance reaches $0 at month 360; the worst-case rate
  //   stops at start + lifetime cap; 0% rates give L / n and $0 interest-only; blank, negative or
  //   inconsistent inputs show an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id) {
    var raw = String(el(id).value).trim();
    if (raw === '') return NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function payment(balance, annualPct, months) {
    if (months <= 0 || balance <= 0) return 0;
    var i = annualPct / 1200;
    if (i === 0) return balance / months;
    return balance * i / (1 - Math.pow(1 + i, -months));
  }

  // o: loan, months, rate, fixedMonths, every, change, firstCap, periodicCap, lifeCap, floor, ioMonths.
  // A fixed-rate loan is a loan whose fixed period covers the whole term.
  function schedule(o) {
    var rate = o.rate, maxRate = o.rate + o.lifeCap, minRate = Math.min(o.floor, o.rate);
    var bal = o.loan, io = o.ioMonths;
    var pay = io > 0 ? bal * rate / 1200 : payment(bal, rate, o.months);
    var rows = [], adj = 0, cumInt = 0, cumPaid = 0;
    for (var m = 1; m <= o.months; m++) {
      var changed = false;
      if (m > o.fixedMonths && (m - o.fixedMonths - 1) % o.every === 0) {
        var cap = adj === 0 ? o.firstCap : o.periodicCap;
        rate = Math.max(minRate, Math.min(maxRate, rate + Math.max(-cap, Math.min(cap, o.change))));
        rate = Math.round(rate * 100000) / 100000;
        adj++;
        changed = true;
      }
      if (io > 0 && m === io + 1) changed = true;
      if (changed) pay = m <= io ? bal * rate / 1200 : payment(bal, rate, o.months - m + 1);
      var interest = bal * rate / 1200;
      var principal = m <= io ? 0 : (m === o.months ? bal : Math.max(0, Math.min(pay - interest, bal)));
      bal -= principal;
      if (bal < 0.005) bal = 0;
      cumInt += interest;
      cumPaid += interest + principal;
      rows.push({ rate: rate, payment: interest + principal, balance: bal, cumInterest: cumInt, cumPaid: cumPaid });
    }
    return rows;
  }

  function maxPayment(rows, upTo) {
    var max = 0;
    for (var m = 0; m < upTo; m++) if (rows[m].payment > max) max = rows[m].payment;
    return max;
  }

  function pct(v) { return (Math.round(v * 1000) / 1000) + '%'; }
  function years(n) { return n + (n === 1 ? ' year' : ' years'); }

  function clearResults() {
    ['aiWinner', 'aiLowPay', 'aiJump'].forEach(function (id) { setText(id, '–'); setText(id + 'Note', ''); });
    el('aiVerdict').hidden = true;
    el('aiCompare').innerHTML = '';
    el('aiSchedule').innerHTML = '';
  }

  function update() {
    var loan = read('aiLoan'), term = read('aiTerm'), horizon = read('aiHorizon'), fixedRate = read('aiFixedRate'),
        armRate = read('aiArmRate'), armFixed = read('aiArmFixed'), ioRate = read('aiIoRate'), ioFixed = read('aiIoFixed'),
        ioYears = read('aiIoYears'), every = parseInt(el('aiEvery').value, 10), change = read('aiChange'),
        firstCap = read('aiFirstCap'), periodicCap = read('aiPeriodicCap'), lifeCap = read('aiLifeCap'), floor = read('aiFloor');
    function whole(v, lo, hi) { return !isNaN(v) && v >= lo && v <= hi && v % 1 === 0; }
    var msg = '';
    if (isNaN(loan) || loan <= 0 || loan > 1e9) msg = 'Enter a loan amount greater than $0.';
    else if (!whole(term, 1, 40)) msg = 'Enter a loan term of 1 to 40 whole years.';
    else if (!whole(horizon, 1, term)) msg = 'Enter how many whole years you expect to keep the loan, up to the loan term.';
    else if ([fixedRate, armRate, ioRate].some(function (v) { return isNaN(v) || v < 0 || v > 30; })) msg = 'Enter interest rates from 0% to 30%.';
    else if (!whole(armFixed, 1, term - 1) || !whole(ioFixed, 1, term - 1)) msg = 'Enter fixed-rate periods of at least 1 whole year that are shorter than the loan term.';
    else if (!whole(ioYears, 1, term - 1)) msg = 'Enter an interest-only period of at least 1 whole year that is shorter than the loan term.';
    else if (isNaN(change) || change < -5 || change > 5) msg = 'Enter an expected change per adjustment from -5% to 5%.';
    else if ([firstCap, periodicCap, lifeCap].some(function (v) { return isNaN(v) || v < 0 || v > 15; })) msg = 'Enter rate caps from 0% to 15%.';
    else if (isNaN(floor) || floor < 0 || floor > 30) msg = 'Enter a rate floor from 0% to 30%.';
    var error = el('aiError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var months = term * 12, h = horizon * 12;
    var base = { loan: loan, months: months, every: every, change: change, firstCap: firstCap, periodicCap: periodicCap, lifeCap: lifeCap, floor: floor };
    function make(rate, fixedMonths, io, chg) {
      var o = {};
      for (var k in base) o[k] = base[k];
      o.rate = rate; o.fixedMonths = fixedMonths; o.ioMonths = io;
      if (chg !== undefined) o.change = chg;
      return schedule(o);
    }
    var loans = [
      { name: 'Fixed rate', lower: 'fixed-rate loan', rows: make(fixedRate, months, 0) },
      { name: 'ARM', lower: 'ARM', rows: make(armRate, armFixed * 12, 0), worst: make(armRate, armFixed * 12, 0, 100) },
      { name: 'Interest-only ARM', lower: 'interest-only ARM', rows: make(ioRate, ioFixed * 12, ioYears * 12), worst: make(ioRate, ioFixed * 12, ioYears * 12, 100) }
    ];
    loans[0].worst = loans[0].rows;
    loans.forEach(function (l) {
      var r = l.rows[h - 1];
      l.first = l.rows[0].payment;
      l.interestH = r.cumInterest;
      l.paidH = r.cumPaid;
      l.balanceH = r.balance;
      l.maxH = maxPayment(l.rows, h);
      l.worstMax = maxPayment(l.worst, months);
      l.worstH = l.worst[h - 1].cumInterest;
    });

    var sorted = loans.slice().sort(function (a, b) { return a.interestH - b.interestH; });
    var best = sorted[0], next = sorted[1];
    if (next.interestH - best.interestH < 0.005) {
      setText('aiWinner', 'A tie');
      setText('aiWinnerNote', 'The ' + best.lower + ' and the ' + next.lower + ' cost the same interest over ' + years(horizon) + '.');
    } else {
      setText('aiWinner', best.name);
      setText('aiWinnerNote', money.format(next.interestH - best.interestH) + ' less interest than the ' + next.lower + ' (next best) over ' + years(horizon) + '.');
    }
    var low = loans.slice().sort(function (a, b) { return a.first - b.first; })[0];
    setText('aiLowPay', money.format(low.first));
    setText('aiLowPayNote', low.name + '. Fixed ' + money.format(loans[0].first) + ', ARM ' + money.format(loans[1].first) + ', interest-only ARM ' + money.format(loans[2].first) + '.');
    var io = loans[2], recast = io.rows[ioYears * 12].payment, jump = recast - io.first;
    setText('aiJump', (jump >= 0 ? '+' : '−') + money.format(Math.abs(jump)));
    setText('aiJumpNote', 'From ' + money.format(io.first) + ' to ' + money.format(recast) + ' a month when principal repayments start in year ' + (ioYears + 1) + (ioYears + 1 > horizon ? ', after your horizon.' : ', within your horizon.'));

    var verdict = el('aiVerdict');
    verdict.hidden = false;
    var fixedL = loans[0];
    var worstBeats = loans.slice(1).filter(function (l) { return l.worstH > fixedL.interestH + 0.005 && l.interestH < fixedL.interestH - 0.005; });
    if (best === fixedL) {
      verdict.className = 'callout callout-note mt-5';
      setText('aiVerdictTitle', 'The fixed rate wins over ' + years(horizon));
      setText('aiVerdictText', 'On the rate path you entered, neither ARM saves interest before you expect to sell or refinance, and the fixed loan carries no rate risk.');
    } else if (worstBeats.length) {
      verdict.className = 'callout callout-warning mt-5';
      setText('aiVerdictTitle', 'Cheaper only if rates behave');
      setText('aiVerdictText', 'The ' + worstBeats.map(function (l) { return l.lower; }).join(' and the ') + ' beat' + (worstBeats.length === 1 ? 's' : '') + ' the fixed loan on your expected rates, but would cost more if rates rise as fast as the caps allow (see the worst-case rows).');
    } else {
      verdict.className = 'callout callout-success mt-5';
      setText('aiVerdictTitle', 'The ' + best.lower + ' costs least over ' + years(horizon));
      setText('aiVerdictText', 'It stays cheaper than the fixed loan over your horizon even if rates rise as fast as the caps allow.' + (best === io ? ' Remember you also repay less principal, so you owe more when you sell.' : ''));
    }

    function row(label, fn) {
      return '<tr><td>' + label + '</td>' + loans.map(function (l) { return '<td>' + fn(l) + '</td>'; }).join('') + '</tr>';
    }
    var H = years(horizon);
    el('aiCompare').innerHTML = [
      row('Starting rate', function (l) { return pct(l.rows[0].rate); }),
      row('First monthly payment', function (l) { return money.format(l.first); }),
      row('Payment at the end of year ' + horizon, function (l) { return money.format(l.rows[h - 1].payment); }),
      row('Highest payment within ' + H, function (l) { return money.format(l.maxH); }),
      row('Highest payment ever, worst-case rates', function (l) { return money.format(l.worstMax); }),
      row('Total paid over ' + H, function (l) { return money.format(l.paidH); }),
      row('Interest over ' + H, function (l) { return money.format(l.interestH); }),
      row('Interest over ' + H + ', worst-case rates', function (l) { return money.format(l.worstH); }),
      row('Principal repaid over ' + H, function (l) { return money.format(loan - l.balanceH); }),
      row('Balance still owed after ' + H, function (l) { return money.format(l.balanceH); })
    ].join('');

    var html = [];
    for (var y = 1; y <= term; y++) {
      var f = loans[0].rows[y * 12 - 1], a = loans[1].rows[y * 12 - 1], b = loans[2].rows[y * 12 - 1];
      html.push('<tr><td>' + y + (y <= horizon ? '*' : '') + '</td><td>' + money.format(f.payment) + '</td><td>' + pct(a.rate) + '</td><td>' +
        money.format(a.payment) + '</td><td>' + pct(b.rate) + '</td><td>' + money.format(b.payment) + '</td><td>' +
        money.format(f.balance) + '</td><td>' + money.format(a.balance) + '</td><td>' + money.format(b.balance) + '</td></tr>');
    }
    el('aiSchedule').innerHTML = html.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('aiForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
